@njit
def mgs(V, w, j, hcol):
    # modified Gram-Schmidt of w against V[:, :j+1], store coeffs in hcol[:j+1]
    n = w.shape[0]
    for i in range(j+1):
        s = 0.0
        Vi = V[:, i]  # numba may not like this in nopython? it does for contiguous
        for t in range(n):
