        hcol[i] += s
        for t in range(n):
            w[t] -= s * Vi[t]
    nrm = 0.0
    for t in range(n):
        nrm += w[t]*w[t]
    return np.sqrt(nrm)

@njit
def arnoldi_build(indptr, indices, data, V, H, w, m):
    n = V.shape[0]
    for j in range(m):
